<?php
$CI =& get_instance();
$store_id = (int)get_current_store_id();
$quote = isset($quotation_id) ? $this->db->where('id', (int)$quotation_id)->where('store_id', $store_id)->get('db_quotation')->row() : null;
$customers = $this->db->select('id, customer_name')->from('db_customers')->where('store_id', $store_id)->where('status', 1)->order_by('customer_name')->get()->result();
$taxes = $this->db->select('id,tax_name,tax')->from('db_tax')->where('store_id',$store_id)->where('status',1)->order_by('tax_name')->get()->result();
$saved_tax = $quote ? $this->db->select('tax_id')->where('quotation_id',$quote->id)->where('store_id',$store_id)->order_by('id')->limit(1)->get('db_quotationitems')->row() : null;
$selected_tax_id = $saved_tax ? (int)$saved_tax->tax_id : 0;
$lines = array();
if($quote){
  $lines = $this->db->select('qi.*, i.item_name, i.item_code, u.unit_name')->from('db_quotationitems qi')
    ->join('db_items i', 'i.id=qi.item_id', 'left')->join('db_units u', 'u.id=i.unit_id', 'left')
    ->where('qi.quotation_id', $quote->id)->where('qi.store_id', $store_id)->order_by('qi.id')->get()->result();
}
$initial_lines = array();
foreach($lines as $line){
  $initial_lines[] = array(
    'item_id' => (int)$line->item_id,
    'name' => $line->manual_item_name ?: $line->item_name,
    'code' => $line->part_code ?: $line->item_code,
    'unit' => $line->unit_label ?: $line->unit_name,
    'description' => $line->description,
    'section' => $line->section_name,
    'qty' => $line->quotation_qty,
    'price' => $line->price_per_unit,
  );
}
$esc = function($value){ return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); };
?>
<style>
