.pq-row{border:1px solid #dde8df;border-radius:14px;padding:16px;margin-bottom:14px;background:#fff}.pq-row-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.pq-row-top strong{color:#14532d}.pq-line-grid{display:grid;grid-template-columns:1fr 1.4fr 1fr .7fr .9fr 1fr;gap:11px;align-items:end}.pq-line-grid .pq-wide{grid-column:span 3}.pq-row-total{text-align:right;color:#14532d;font-weight:800;font-size:17px}.pq-pick-wrap{position:relative;max-width:480px}.pq-pick{position:absolute;top:100%;left:0;right:0;z-index:30;background:#fff;border:1px solid #bedbc7;border-radius:10px;box-shadow:0 12px 24px rgba(0,0,0,.12);max-height:220px;overflow-y:auto;display:none}.pq-pick button{display:block;text-align:left;border:0;border-bottom:1px solid #edf2ed;background:#fff;width:100%;padding:10px 13px;cursor:pointer}.pq-pick button:hover,.pq-pick button:focus{background:#edf8f0}.pq-pick small{display:block;color:#64748b}.pq-tools{display:flex;gap:9px;flex-wrap:wrap;margin-top:8px}.pq-btn{border:1px solid #b9d5c1;border-radius:9px;padding:10px 15px;background:#fff;color:#166534;font-weight:700;cursor:pointer}.pq-btn-primary{background:#166534;color:#fff;border-color:#166534}.pq-delete{border:0;background:#fff;color:#b42318;font-weight:700;cursor:pointer}.pq-summary{display:flex;justify-content:flex-end;gap:36px;align-items:center;font-size:18px;font-weight:800}.pq-summary strong{font-size:24px;color:#14532d}.pq-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.pq-note{color:#64748b;font-size:12px;margin:8px 0}.pq-error{color:#b42318;font-weight:700;margin:10px 0;display:none}
@media(max-width:900px){.pq-line-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.pq-line-grid .pq-wide{grid-column:span 3}}
