.pq-customer-trigger{width:100%;text-align:left;border:1px solid #d8e2db;border-radius:9px;background:#fff;padding:12px;color:#173128}.pq-customer-options{max-height:220px;overflow-y:auto;border:1px solid #d8e2db;border-radius:9px;margin-top:5px}.pq-customer-options button{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #e8eee9;background:#fff;padding:12px;color:#173128}
.pq-group{border:1px solid #cfe3d5;border-radius:16px;background:#f8fbf9;margin:0 0 20px;overflow:visible}.pq-group-head{display:flex;align-items:flex-end;gap:16px;padding:18px;border-bottom:1px solid #e0ece3}.pq-group-head .pq-field{flex:1}.pq-group-head .pq-delete{padding:10px}.pq-group-body{padding:18px}.pq-group .pq-row{box-shadow:0 2px 8px rgba(25,70,45,.035)}.pq-group .pq-pick-wrap{margin-bottom:16px}.pq-group .pq-tools{margin-top:4px}
@media(max-width:620px){.pq-group-head{align-items:stretch;flex-direction:column;gap:4px;padding:14px}.pq-group-head .pq-delete{align-self:flex-end}.pq-group-body{padding:12px}.pq-pick{position:static;box-shadow:none;margin-top:5px}.pq-tools .pq-btn{width:100%}}
