<div class="pq-shell">
  <?php if(empty($plant_mobile)): ?><div class="pq-top"><div><h2><?= $quote ? 'Edit Quotation' : 'New Quotation' ?></h2><p>Build a clear offer for parts, services, or any plant work.</p></div><a class="pq-back" href="<?= base_url('quotation') ?>">← Quotations</a></div><?php endif; ?>
  <form id="plant-quotation-form" action="<?= base_url('quotation/plant_save') ?>" method="post">
    <?php if($quote): ?><input type="hidden" name="quotation_id" value="<?= (int)$quote->id ?>"><?php endif; ?>
    <?= $this->security->get_csrf_token_name() ? '<input type="hidden" name="'.$esc($this->security->get_csrf_token_name()).'" value="'.$esc($this->security->get_csrf_hash()).'">' : '' ?>
    <div class="pq-card"><div class="pq-head"><span class="pq-step">1</span> Client &amp; quotation</div><div class="pq-body pq-grid">
      <div class="pq-field"><label for="pq-customer">Client *</label><select id="pq-customer" name="customer_id" <?= empty($plant_mobile) ? 'required' : 'style="display:none"' ?>><option value="">Choose client</option><?php foreach($customers as $customer): ?><option value="<?= (int)$customer->id ?>" <?= $quote && (int)$quote->customer_id === (int)$customer->id ? 'selected' : '' ?>><?= $esc($customer->customer_name) ?></option><?php endforeach; ?></select><?php if(!empty($plant_mobile)): ?><button type="button" id="pq-customer-trigger" class="pq-customer-trigger">Choose client</button><div id="pq-customer-options" class="pq-customer-options" hidden><?php foreach($customers as $customer): ?><button type="button" data-value="<?= (int)$customer->id ?>"><?= $esc($customer->customer_name) ?></button><?php endforeach; ?></div><?php endif; ?></div>
      <div class="pq-field"><label for="pq-reference">Reference</label><input id="pq-reference" name="reference_no" value="<?= $esc($quote->reference_no ?? '') ?>" placeholder="e.g. Pressing line spares"></div>
      <div class="pq-field"><label for="pq-date">Quotation date *</label><input id="pq-date" name="quotation_date" class="datepicker" required value="<?= $esc($quote ? show_date($quote->quotation_date) : show_date(date('Y-m-d'))) ?>"></div>
      <div class="pq-field"><label for="pq-expiry">Valid until</label><input id="pq-expiry" name="expire_date" class="datepicker" value="<?= $esc($quote && $quote->expire_date ? show_date($quote->expire_date) : '') ?>"></div>
    </div></div>
    <div class="pq-card"><div class="pq-head"><span class="pq-step">2</span> Quotation lines</div><div class="pq-body">
      <p class="pq-note">Give each group a heading once. Search for saved items or add custom lines inside that group. Part codes stay on individual lines.</p>
      <p class="pq-note">Need to reuse a new part later? <a href="<?= base_url(!empty($plant_mobile) ? 'mobile/product' : 'items/add') ?>" target="_blank" rel="noopener">Create a material / product with its part code</a>, then search for it here.</p>
      <button type="button" id="pq-load-sample" class="pq-btn" style="margin-bottom:16px"><i class="fa fa-file-excel-o"></i> Load Hykeng example</button>
      <div id="pq-groups"></div>
      <div class="pq-tools"><button type="button" id="pq-add-group" class="pq-btn"><i class="fa fa-folder-open-o"></i> Add another group</button></div>
    </div></div>
    <div class="pq-card"><div class="pq-head"><span class="pq-step">3</span> Tax, notes &amp; total</div><div class="pq-body">
      <div class="pq-field" style="max-width:480px;margin-bottom:16px"><label for="pq-tax">Tax rate</label><select id="pq-tax" name="tax_id" <?= !empty($plant_mobile) ? 'style="display:none"' : '' ?>><option value="" data-rate="0">No tax</option><?php foreach($taxes as $tax): ?><option value="<?= (int)$tax->id ?>" data-rate="<?= $esc($tax->tax) ?>" <?= $selected_tax_id === (int)$tax->id ? 'selected' : '' ?>><?= $esc($tax->tax_name) ?> (<?= $esc($tax->tax) ?>%)</option><?php endforeach; ?></select><?php if(!empty($plant_mobile)): ?><button type="button" id="pq-tax-trigger" class="pq-customer-trigger">Choose tax rate</button><div id="pq-tax-options" class="pq-customer-options" hidden><?php foreach($taxes as $tax): ?><button type="button" data-value="<?= (int)$tax->id ?>"><?= $esc($tax->tax_name) ?> (<?= $esc($tax->tax) ?>%)</button><?php endforeach; ?><button type="button" data-value="">No tax</button></div><?php endif; ?><small class="pq-note">Tax is added to line prices. <a href="<?= base_url(!empty($plant_mobile) ? 'oil_processing/tax_rates' : 'tax') ?>">Manage tax rates</a></small></div>
      <div class="pq-field"><label for="pq-note">Terms or notes for the client</label><textarea id="pq-note" name="quotation_note" placeholder="Delivery time, payment terms, exclusions…"><?= $esc($quote->quotation_note ?? '') ?></textarea></div><div class="pq-summary"><span>Subtotal</span><strong id="pq-subtotal"><?= $esc($CI->currency()) ?>0.00</strong></div><div class="pq-summary"><span>Tax</span><strong id="pq-tax-amount"><?= $esc($CI->currency()) ?>0.00</strong></div><div class="pq-summary"><span>Quotation total</span><strong id="pq-total"><?= $esc($CI->currency()) ?>0.00</strong></div><div id="pq-error" class="pq-error" role="alert"></div><div class="pq-actions"><a class="pq-btn" href="<?= base_url(!empty($plant_mobile) ? 'mobile/quotations' : 'quotation') ?>">Cancel</a><button class="pq-btn pq-btn-primary" type="submit" id="pq-save">Save quotation</button></div></div></div>
  </form>
</div>
<script>
(function(){
  var initial = <?= json_encode($initial_lines, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
  var searchUrl = <?= json_encode(base_url('quotation/plant_item_search')) ?>;
  var sampleUrl = <?= json_encode(base_url('quotation/plant_sample')) ?>;
  var currency = <?= json_encode($CI->currency()) ?>;
  var groups = document.getElementById('pq-groups');
  var next = 0;
  function field(label,key,value,type,extra){var box=document.createElement('div');box.className='pq-field'+(extra?' '+extra:'');var caption=document.createElement('label');caption.textContent=label;box.appendChild(caption);var input=document.createElement(key==='description'?'textarea':'input');if(input.tagName==='INPUT')input.type=type||'text';input.name='lines['+next+']['+key+']';input.value=value==null?'':value;if(type==='number'){input.min=key==='qty'?'0.001':'0';input.step='any';}box.appendChild(input);return box;}
  function renumber(group){Array.prototype.forEach.call(group.querySelectorAll('.pq-row-top strong'),function(title,index){title.textContent='Line '+(index+1);});}
  function starterLine(group){var rows=group.querySelectorAll('.pq-row');if(rows.length!==1)return null;var row=rows[0];var value=function(key){return row.querySelector('[name$="['+key+']"]').value.trim();};return !value('item_id')&&!value('code')&&!value('name')&&!value('description')&&!value('unit')&&value('qty')==='1'&&Number(value('price'))===0?row:null;}
  function addLine(group,data,focus){data=data||{};var row=document.createElement('div');row.className='pq-row';var top=document.createElement('div');top.className='pq-row-top';var title=document.createElement('strong');top.appendChild(title);var remove=document.createElement('button');remove.type='button';remove.className='pq-delete';remove.textContent='Remove';remove.onclick=function(){row.remove();renumber(group);total();};top.appendChild(remove);row.appendChild(top);var grid=document.createElement('div');grid.className='pq-line-grid';grid.appendChild(field('Part code','code',data.code||''));grid.appendChild(field('Description *','name',data.name||'','text','pq-wide'));grid.appendChild(field('Details','description',data.description||'','text','pq-wide'));grid.appendChild(field('Quantity *','qty',data.qty==null?1:data.qty,'number'));grid.appendChild(field('Unit','unit',data.unit||''));grid.appendChild(field('Unit price *','price',data.price==null?0:data.price,'number'));var subtotal=document.createElement('div');subtotal.className='pq-row-total pq-wide';grid.appendChild(subtotal);var item=document.createElement('input');item.type='hidden';item.name='lines['+next+'][item_id]';item.value=data.item_id||'';row.appendChild(item);var section=document.createElement('input');section.type='hidden';section.name='lines['+next+'][section]';section.value=group.querySelector('.pq-group-name').value;row.appendChild(section);row.appendChild(grid);group.querySelector('.pq-group-lines').appendChild(row);grid.addEventListener('input',total);next++;renumber(group);total();if(focus)row.querySelector('[name$="[name]"]').focus();}
  function createGroup(name,focus){var group=document.createElement('section');group.className='pq-group';var head=document.createElement('div');head.className='pq-group-head';var heading=document.createElement('div');heading.className='pq-field';var label=document.createElement('label');label.textContent='Group heading';var input=document.createElement('input');input.type='text';input.className='pq-group-name';input.placeholder='e.g. Spare parts EK-200K (first pressing)';input.value=name||'';label.appendChild(input);heading.appendChild(label);head.appendChild(heading);var remove=document.createElement('button');remove.type='button';remove.className='pq-delete';remove.textContent='Remove group';remove.onclick=function(){var filled=Array.prototype.some.call(group.querySelectorAll('.pq-row'),function(row){return row.querySelector('[name$="[name]"]').value.trim();});if(filled&&!window.confirm('Remove this group and all its lines?'))return;group.remove();if(!groups.children.length){var blank=createGroup('',false);addLine(blank,{},false);}total();};head.appendChild(remove);group.appendChild(head);var body=document.createElement('div');body.className='pq-group-body';var picker=document.createElement('div');picker.className='pq-field pq-pick-wrap';var pickLabel=document.createElement('label');pickLabel.textContent='Find an existing item for this group';var search=document.createElement('input');search.type='search';search.autocomplete='off';search.placeholder='Search part name or code';pickLabel.appendChild(search);picker.appendChild(pickLabel);var results=document.createElement('div');results.className='pq-pick';results.setAttribute('role','listbox');picker.appendChild(results);body.appendChild(picker);var lineContainer=document.createElement('div');lineContainer.className='pq-group-lines';body.appendChild(lineContainer);var tools=document.createElement('div');tools.className='pq-tools';var add=document.createElement('button');add.type='button';add.className='pq-btn';add.textContent='+ Add line in this group';add.onclick=function(){var starter=starterLine(group);if(starter){starter.querySelector('[name$="[name]"]').focus();return;}addLine(group,{},true);};tools.appendChild(add);body.appendChild(tools);group.appendChild(body);groups.appendChild(group);input.addEventListener('input',function(){Array.prototype.forEach.call(group.querySelectorAll('input[name$="[section]"]'),function(hidden){hidden.value=input.value;});});var timer;search.addEventListener('input',function(){clearTimeout(timer);var term=search.value.trim();results.style.display='none';if(term.length<2)return;timer=setTimeout(function(){fetch(searchUrl+'?q='+encodeURIComponent(term),{credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error('Search unavailable');return r.json();}).then(function(items){if(!group.parentNode||search.value.trim()!==term)return;results.innerHTML='';items.forEach(function(item){var button=document.createElement('button');button.type='button';button.textContent=(item.item_code?item.item_code+' · ':'')+item.item_name;var detail=document.createElement('small');detail.textContent=(item.unit_name||'')+(item.sales_price?' · '+currency+Number(item.sales_price).toLocaleString():'');button.appendChild(detail);button.onclick=function(){var starter=starterLine(group);if(starter)starter.remove();addLine(group,{item_id:item.id,name:item.item_name,code:item.item_code,description:item.description,unit:item.unit_name,price:item.sales_price},false);search.value='';results.style.display='none';};results.appendChild(button);});if(!items.length){var empty=document.createElement('button');empty.type='button';empty.textContent='No saved item found — add a line manually';empty.onclick=function(){var starter=starterLine(group);if(starter)starter.remove();addLine(group,{name:term},true);search.value='';results.style.display='none';};results.appendChild(empty);}results.style.display='block';}).catch(function(){results.innerHTML='';var message=document.createElement('small');message.textContent='Could not search items. You can add a line manually.';results.appendChild(message);results.style.display='block';});},220);});if(focus)input.focus();return group;}
  function populate(source){groups.innerHTML='';next=0;var group=null,last=null;source.forEach(function(line){var heading=line.section||'';if(!group||heading!==last){group=createGroup(heading,false);last=heading;}addLine(group,line,false);});if(!group){group=createGroup('',false);addLine(group,{},false);}total();}
  function total(){var sum=0,tax=0,taxSelect=document.getElementById('pq-tax'),rate=parseFloat(taxSelect.options[taxSelect.selectedIndex].getAttribute('data-rate'))||0;Array.prototype.forEach.call(groups.querySelectorAll('.pq-row'),function(row){var qty=parseFloat(row.querySelector('[name$="[qty]"]').value)||0;var price=parseFloat(row.querySelector('[name$="[price]"]').value)||0;var amount=Math.round(qty*price*100)/100,lineTax=Math.round(amount*rate)/100;row.querySelector('.pq-row-total').textContent=currency+(amount+lineTax).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});sum+=amount;tax+=lineTax;});document.getElementById('pq-subtotal').textContent=currency+sum.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById('pq-tax-amount').textContent=currency+tax.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById('pq-total').textContent=currency+(sum+tax).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});}
  document.getElementById('pq-tax').addEventListener('change',total);
  var taxTrigger=document.getElementById('pq-tax-trigger'),taxOptions=document.getElementById('pq-tax-options');if(taxTrigger&&taxOptions){var taxSelect=document.getElementById('pq-tax');taxTrigger.textContent=taxSelect.options[taxSelect.selectedIndex].text;taxTrigger.onclick=function(){taxOptions.hidden=!taxOptions.hidden;};Array.prototype.forEach.call(taxOptions.querySelectorAll('button'),function(button){button.onclick=function(){taxSelect.value=button.getAttribute('data-value');taxTrigger.textContent=button.textContent;taxOptions.hidden=true;total();};});}
  document.getElementById('pq-add-group').onclick=function(){var group=createGroup('',true);addLine(group,{},false);};
  document.getElementById('pq-load-sample').onclick=function(){var filled=Array.prototype.some.call(groups.querySelectorAll('.pq-row'),function(row){return row.querySelector('[name$="[name]"]').value.trim();});if(filled&&!window.confirm('Replace the current quotation lines with the Hykeng example?'))return;fetch(sampleUrl,{credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error('Sample unavailable');return r.json();}).then(function(sample){populate(sample.lines||[]);document.getElementById('pq-tax').value='';if(taxTrigger)taxTrigger.textContent='No tax';document.getElementById('pq-reference').value=sample.reference;document.getElementById('pq-note').value=sample.note;document.getElementById('pq-error').style.display='none';window.scrollTo({top:0,behavior:'smooth'});}).catch(function(){var error=document.getElementById('pq-error');error.textContent='Could not load the example.';error.style.display='block';});};
  var customerTrigger=document.getElementById('pq-customer-trigger'),customerOptions=document.getElementById('pq-customer-options');if(customerTrigger&&customerOptions){var customerSelect=document.getElementById('pq-customer');customerTrigger.textContent=customerSelect.options[customerSelect.selectedIndex].text;customerTrigger.onclick=function(){customerOptions.hidden=!customerOptions.hidden;};Array.prototype.forEach.call(customerOptions.querySelectorAll('button'),function(button){button.onclick=function(){customerSelect.value=button.getAttribute('data-value');customerTrigger.textContent=button.textContent;customerOptions.hidden=true;};});}
  document.addEventListener('click',function(e){if(!e.target.closest('.pq-pick-wrap'))Array.prototype.forEach.call(groups.querySelectorAll('.pq-pick'),function(result){result.style.display='none';});});
  populate(initial);
  var form=document.getElementById('plant-quotation-form');form.addEventListener('submit',function(e){e.preventDefault();var error=document.getElementById('pq-error');error.style.display='none';var rows=groups.querySelectorAll('.pq-row'),valid=0;Array.prototype.forEach.call(rows,function(row){if(row.querySelector('[name$="[name]"]').value.trim())valid++;});if(!document.getElementById('pq-customer').value){error.textContent='Choose a client.';error.style.display='block';return;}if(!valid){error.textContent='Add at least one line description.';error.style.display='block';return;}var save=document.getElementById('pq-save');save.disabled=true;fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json();}).then(function(result){if(result.success){window.location.href=<?= json_encode(base_url(!empty($plant_mobile) ? 'mobile/quotations' : 'quotation')) ?>;return;}error.textContent=result.message||'Could not save quotation.';error.style.display='block';if(result.csrf_hash){var csrf=form.querySelector('input[name=<?= json_encode($this->security->get_csrf_token_name()) ?>]');if(csrf)csrf.value=result.csrf_hash;}}).catch(function(){error.textContent='Could not save quotation. Please try again.';error.style.display='block';}).then(function(){save.disabled=false;});});
})();
</script>
